def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    objects = []

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)

        # Keep only rectangular frames with no other-colored cells inside.
        frame = all(grid[r0][c] == color and grid[r1][c] == color
                    for c in range(c0, c1 + 1))
        frame = frame and all(grid[r][c0] == color and grid[r][c1] == color
                              for r in range(r0, r1 + 1))
        if not frame or r1 - r0 < 2 or c1 - c0 < 2:
            continue

        pattern = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                   for r in range(r0 + 1, r1)]
        objects.append((color, r0, r1, c0, c1, pattern))

    templates = [obj for obj in objects if any(any(row) for row in obj[5])]
    out = [[0] * w for _ in range(h)]

    for color, r0, r1, c0, c1, pattern in templates:
        ih, iw = len(pattern), len(pattern[0])
        for target_color, a, b, x, y, _ in objects:
            if b - a - 1 != ih or y - x - 1 != iw:
                continue
            for c in range(x, y + 1):
                out[a][c] = out[b][c] = target_color
            for r in range(a, b + 1):
                out[r][x] = out[r][y] = target_color
            for i in range(ih):
                for j in range(iw):
                    if pattern[i][j]:
                        out[a + 1 + i][x + 1 + j] = target_color

    return out
